from lib import *
S = SS('k19')
F1 = [['kubelet', 'TokenRequest(expirationSeconds=3607)'], ['API Server 签发', 'JWT,绑定 Pod + 节点'], ['projected 卷', 'kube-api-access-xxxxx'], ['Pod 里的进程', '读 /var/run/secrets/…/token']]
F2 = [['新 SA 没有 Secret', 'kubectl get secret 为空'], ['手工建 Secret', 'type=service-account-token'], ['token 控制器填令牌', '无 exp,无 Pod 绑定'], ['删除 Secret', '11 秒后 401']]
F3 = [['SA: false', '没有挂载'], ['Pod: false', '没有挂载'], ['SA: false + Pod: true', '挂载(Pod 优先)']]
F4 = [['kubelet', '令牌年龄 ≥ 80%'], ['TokenRequest', '取新令牌'], ['..data 符号链接', '原子切换到新目录'], ['第 497 秒', '600 秒有效期的 83%']]
PANELS = [('f', 'flow', 'ServiceAccount 令牌'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod app 里的 /var/run/secrets/kubernetes.io/serviceaccount/token 是一个 JWT:iss=https://kubernetes.default.svc.cluster.local,aud 是 API Server 的受众,sub=system:serviceaccount:k19:default,kubernetes.io 里有 namespace、serviceaccount、pod=app、node=kx-main-worker2,还有 jti。iat→exp 是 31536000 秒(365 天),而卷里声明的 expirationSeconds=3607;拿它调用 SelfSubjectReview:HTTP 201,extra 里有 pod-name、pod-uid、node-name、node-uid、credential-id。kube-apiserver 没有设置 --service-account-extend-token-expiration 与 --service-account-max-token-expiration。", f=fl(F1, cur=[1], done=[0, 2, 3]), t=tl(S(1), mark=lidx(S(1), 'iat→exp', 'kubernetes.io 里'), done=lidx(S(1), 'claims:', '拿这个令牌调用')), kv=KV([['绑定', '令牌绑定到这个 Pod 和它所在的节点'], ['exp', '365 天:apiserver 默认延长默认受众令牌的有效期'], ['真正的轮换', 'kubelet 按卷里的 expirationSeconds 刷新']], ['exp'])),
    step("新建的 ServiceAccount 命名空间里 kubectl get secret 为空(不再自动生成长期令牌)。手工创建 type=kubernetes.io/service-account-token 并带 service-account.name 注解的 Secret,token 控制器几乎立刻填上令牌:claims 里没有 exp,没有 Pod 和 Node 绑定,有 kubernetes.io/serviceaccount/secret.name=legacy;可以调用 API。删掉这个 Secret 后,同一个令牌 9 秒内仍通过认证,第 11 秒起 HTTP 401。", f=fl(F2, cur=[2], mark=[3], done=[0, 1]), t=tl(S(2), mark=lidx(S(2), '有 exp 吗', '第 11 秒起'), done=lidx(S(2), 'No resources found', '用它调用')), kv=KV([['不再自动生成', '需要时自己建 Secret 才有长期令牌'], ['旧式令牌', '没有过期时间,不绑定 Pod'], ['删除 Secret', '令牌作废,但有约 10 秒的缓存']], ['旧式令牌'])),
    step("不要令牌:默认的 app 挂载了 ca.crt、namespace、token 三个文件(spec.volumes 里有 kube-api-access-…);SA 上 automountServiceAccountToken: false 的 Pod 没有这个目录、spec.volumes 为空;Pod 上设 false 同样;SA 为 false 而 Pod 上设为 true 时又挂载了——Pod 上的设置优先于 ServiceAccount。", f=fl(F3, cur=[2], done=[0, 1]), t=tl(S(3), mark=lidx(S(3), 'No such file', 'p-override'), done=lidx(S(3), 'app(默认 SA')), kv=KV([['automountServiceAccountToken', '可以设在 SA 或 Pod 上'], ['冲突时', 'Pod 的设置优先'], ['不需要访问 API 的应用', '建议关掉']], ['冲突时'])),
    step("令牌会换:projected 令牌设 expirationSeconds=600、audience=rotate-test,每 10 秒读一次文件。第 0 秒 iat=1791624502,有效期 600 秒;第 497 秒出现新令牌(iat=1791624999),约为 600 秒有效期的 83%,卷里的 ..data 符号链接从 ..2026_10_10_09_28_22… 换到 ..2026_10_10_09_36_39…——kubelet 在令牌年龄超过 80% 之后刷新,并用符号链接原子切换。567 秒内只出现了 2 个版本。", f=fl(F4, cur=[2], done=[0, 1], mark=[3]), t=tl(S(4), mark=lidx(S(4), '第  497 秒', '..data → ..2026_10_10_09_36_39'), done=lidx(S(4), '第    0 秒', '第二个令牌出现在')), kv=KV([['刷新时机', '年龄超过有效期的 80% 之后'], ['原子替换', '..data 符号链接指向新目录'], ['应用要做的', '每次使用都重新读文件,不要缓存一辈子']], ['应用要做的'])),
]
A = mkartk('k19', 19, 'Kubernetes,ServiceAccount,projected 令牌,kubelet,令牌轮换,automountServiceAccountToken,真实验证,动画演示',
    '在 kind 集群里解开 Pod 里的 ServiceAccount 令牌:绑定 Pod 与节点的 JWT,卷里声明 expirationSeconds=3607 而令牌 exp 是 365 天(apiserver 默认延长);新 SA 不再自动生成 Secret 令牌,手工建的旧式令牌没有 exp、不绑定 Pod,删除 Secret 后 11 秒才 401;automountServiceAccountToken 在 SA 与 Pod 上冲突时 Pod 优先;自定义 600 秒受众的令牌在年龄约 83% 时被 kubelet 刷新,..data 符号链接原子切换。',
    'Pod 里 /var/run/secrets/kubernetes.io/serviceaccount/token 到底是什么?它是怎么来的、什么时候换、和以前那种永不过期的 Secret 令牌有什么区别?这篇把令牌 JWT 解开,逐个声明读一遍,再观察 kubelet 的刷新,并验证 automount 的优先级。',
    [('365 天 vs 3607 秒', '默认受众令牌的 exp - iat,与卷里声明的 expirationSeconds(kubelet 以后者为准刷新)'), ('11 秒', '删除旧式 Secret 令牌的 Secret 之后,令牌从第几秒起返回 401'), ('83%', '600 秒有效期的令牌被 kubelet 刷新时的年龄占比(第 497 秒)')],
    [('Pod 里的令牌是什么', '<p>kubelet 通过 TokenRequest 为 Pod 取一个令牌,放进自动挂载的 projected 卷。解开 JWT:<code>iss</code> 是集群的 issuer,<code>aud</code> 是 API Server 的受众,<code>sub</code> 是 <code>system:serviceaccount:k19:default</code>,<code>kubernetes.io</code> 里有 <code>namespace</code>、<code>serviceaccount</code>、<code>pod</code>、<code>node</code> 以及 <code>jti</code>。拿它调用 API,身份的 <code>extra</code> 里带 <code>pod-name</code>、<code>pod-uid</code>、<code>node-name</code>——令牌是绑定到这个 Pod 的。</p><p>卷里写的 <code>expirationSeconds</code> 是 3607,令牌的 <code>exp - iat</code> 却是 31536000 秒(365 天):这个集群的 kube-apiserver 没有设置 <code>--service-account-extend-token-expiration</code>,默认会延长默认受众令牌的有效期,让还没来得及升级的客户端不至于立刻失效;kubelet 仍按 3607 秒的 80% 去刷新。</p>'),
     ('旧式 Secret 令牌', '<p>新建的 ServiceAccount 命名空间里 <code>kubectl get secret</code> 是空的,不再自动生成长期令牌。要的话手工创建 <code>type: kubernetes.io/service-account-token</code> 并带 <code>kubernetes.io/service-account.name</code> 注解的 Secret,token 控制器几乎立刻填上令牌:claims 里没有 <code>exp</code>,没有 Pod 和 Node 绑定,只有 <code>kubernetes.io/serviceaccount/secret.name</code> 等。它能调用 API,直到 Secret 被删——删掉之后又过了 11 秒才开始 401(认证结果有短暂缓存)。永不过期、泄漏了就一直有效,所以尽量别用。</p>'),
     ('不要令牌', '<p>不需要访问 API 的应用不该有令牌。<code>automountServiceAccountToken: false</code> 设在 ServiceAccount 或 Pod 上都能让 Pod 里没有这个目录(<code>spec.volumes</code> 也不再有 <code>kube-api-access-…</code>);两处冲突时 Pod 上的设置优先:SA 设 false、Pod 设 true,令牌还是挂了。</p>'),
     ('令牌会自己换', '<p>用最短的 <code>expirationSeconds: 600</code> 加自定义受众观察:第 0 秒的令牌 <code>exp - iat = 600</code>(自定义受众不延长);第 497 秒文件里出现了新令牌,这时旧令牌年龄是有效期的 83%——kubelet 在年龄超过 80% 之后刷新。更新是原子的:卷里的 <code>..data</code> 符号链接从旧的时间戳目录切到新的,<code>token</code> 文件始终是完整的。应用要每次使用时重新读文件(client-go 已经这样做),不要在启动时读一次就缓存一辈子。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,kube-apiserver 没有设置令牌有效期相关的两个参数,默认值);JWT 的声明在宿主机上解码,调用 API 用 SelfSubjectReview;令牌文件用 kubectl exec 读出,卷里的符号链接用 readlink 看;旧式令牌失效时间由每秒一次的轮询得到;轮换观察用 expirationSeconds=600、audience=rotate-test,每 10 秒读一次,共 567 秒,第二个令牌出现在第 497 秒;每种情形各一次',
     '没有验证:365 天的延长是否会写入审计日志的注解;关闭 --service-account-extend-token-expiration 后的行为;令牌被延长后过期前的警告与指标(serviceaccount_stale_tokens_total);轮换的精确触发时机(kubelet 的刷新检查间隔,只观察到 83%);projected 卷里 configMap 与 downwardAPI 的更新;ServiceAccount 的 imagePullSecrets;令牌在节点失联时的使用'],
    'ServiceAccount 令牌', PANELS)
